    "keyFactsHtml": "<table>\n<thead>\n<tr>\n<th>Параметр</th>\n<th>Значение</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Что называют фольгой</td>\n<td>чаще — ленту тоньше 0,1 мм; единой границы в стандартах нет</td>\n</tr>\n<tr>\n<td>Толщина тонкой ленты в каталоге</td>\n<td>от 0,01 мм (в целом 0,01–4 мм)</td>\n</tr>\n<tr>\n<td>Ширина в каталоге</td>\n<td>3–250 мм</td>\n</tr>\n<tr>\n<td>Нижняя граница толщины в ГОСТ 4986-79</td>\n<td>0,05 мм (по справочнику сайта)</td>\n</tr>\n<tr>\n<td>Марки нержавеющей ленты в каталоге</td>\n<td>12Х18Н10Т, 08Х18Н10, 12Х18Н9, 12Х18Н9СМР, 10Х17Н13М3Т</td>\n</tr>\n<tr>\n<td>Состояние в каталоге</td>\n<td>нагартованное и высоконагартованное</td>\n</tr>\n<tr>\n<td>Поверхность</td>\n<td>обычная или блестящая</td>\n</tr>\n<tr>\n<td>Масса 1 м ленты 0,02 × 100 мм (12Х18Н10Т)</td>\n<td>около 16 г</td>\n</tr>\n<tr>\n<td>Срок</td>\n<td>под заказ</td>\n</tr>\n</tbody>\n</table>",
